const sites=[{id:'lab',name:'BIG CRACK LAB',action:'ENTER LAB',pos:[293,345],range:58},{id:'rig',name:'MAIN MINING RIG',action:'OPERATE RIG',pos:[656,385],range:75},{id:'oil',name:'OIL SUPPLY DEPOT',action:'OPEN SHOP',pos:[787,481],range:58},{id:'security',name:'SECURITY CONTROL',action:'VIEW CAMERAS',pos:[315,451],range:54}];
function nearest(){let found=null,dist=Infinity;for(const s of sites){const d=Math.hypot(s.pos[0]-state.player.x,s.pos[1]-state.player.y);if(d<s.range&&d<dist){found=s;dist=d}}return found}
function updateInteract(){const n=nearest(),hint=$('interact-hint');if(n){hint.classList.add('show');$('interact-label').textContent=n.action;$('interact-label').previousElementSibling.textContent='E'}else hint.classList.remove('show');$('map-player').style.left=`${clamp(state.player.x/1000*145+3,0,150)}px`;$('map-player').style.top=`${clamp(state.player.y/650*78+3,0,78)}px`}
function interact(site=nearest()){if(!site){toast('Move closer to a facility station to interact');return}if(site.id==='rig'){if(!state.powered){openQuiz();return}toggleRig()}if(site.id==='lab')openLab();if(site.id==='oil')openShop('oil');if(site.id==='security')openCameras()}
function toggleRig(){if(!state.powered){toast('POWER INTERRUPTED · restore facility electricity');openQuiz();return}if(state.running){state.running=false;toast('Rig operation stopped');return}if(state.oil<=0){toast('OUT OF OIL · resupply at the depot');openShop('oil');return}if(state.condition<=0){toast('RIG OFFLINE · service required at the lab');openLab();return}state.running=true;toast('Rig online · drilling sequence engaged');playTone(360,.08)}
function showModal(title,subtitle,eyebrow,body){$('modal').innerHTML=`<div class="modal-head"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2><p>${subtitle}</p></div><button class="close-modal" aria-label="Close">×</button></div><div class="modal-body">${body}</div>`;$('modal-backdrop').classList.add('open');state.modal='generic';$('modal').querySelector('.close-modal').onclick=closeModal;}
function closeModal(){if(state.modal==='quiz'&&!state.powered)return;$('modal-backdrop').classList.remove('open');state.modal='';}
function openShop(tab=state.shopTab){state.shopTab=tab;const tabs=`<div class="shop-tabs"><button class="shop-tab ${tab==='oil'?'active':''}" data-tab="oil">OIL SUPPLY</button><button class="shop-tab ${tab==='equipment'?'active':''}" data-tab="equipment">EQUIPMENT</button></div>`;let body=tabs;
  if(tab==='oil'){body+=`<div class="item-grid">${oilTypes.map((o,i)=>`<article class="item-card"><div class="item-symbol">◉</div><span class="level-tag">${o.seconds} SEC SUPPLY</span><h3>${o.name}</h3><p>${o.desc}</p><div class="item-bottom"><span class="price">$${money(o.price)}</span><button class="buy-btn" data-oil="${i}" ${state.money<o.price?'disabled':''}>PURCHASE</button></div></article>`).join('')}</div><div class="modal-foot"><span>CURRENT SUPPLY: ${oilTypes[state.oilType].name.toUpperCase()}</span><span>${Math.ceil(state.oil)} SEC REMAINING</span></div>`}else{body+=`<div class="item-grid"><article class="item-card"><div class="item-symbol">⚙</div><span class="level-tag">SERVICE</span><h3>Rig maintenance</h3><p>Restore 35 points of machine integrity in the field.</p><div class="item-bottom"><span class="price">$280</span><button class="buy-btn" data-service="true" ${state.money<280||state.condition>=100?'disabled':''}>SERVICE</button></div></article><article class="item-card"><div class="item-symbol">▤</div><span class="level-tag">FIELD KIT</span><h3>Emergency oil drum</h3><p>A basic 60-second oil supply for an active drill.</p><div class="item-bottom"><span class="price">$90</span><button class="buy-btn" data-oil="0" ${state.money<90?'disabled':''}>PURCHASE</button></div></article></div>`}
  showModal('Supply depot','Field consumables & operational equipment','SUPPLY CHAIN · DEPOT 07',body);$('modal').querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>openShop(b.dataset.tab));$('modal').querySelectorAll('[data-oil]').forEach(b=>b.onclick=()=>buyOil(+b.dataset.oil));const svc=$('modal').querySelector('[data-service]');if(svc)svc.onclick=serviceRig;}
function buyOil(i){const o=oilTypes[i];if(state.money<o.price){toast('Insufficient funds');return}state.money-=o.price;state.oilType=i;state.oil=Math.min(o.seconds*(1+state.upgrades.efficiency*.2),state.oil+o.seconds*(1+state.upgrades.efficiency*.2));if(state.oil>0&&state.powered&&state.condition>0)toast(`${o.name} delivered · ${Math.ceil(state.oil)} seconds reserve`);if(state.oil>0&&state.powered&&state.condition>0&&state.modal==='')state.running=true;updateHud();openShop('oil');save()}
function serviceRig(){if(state.money<280){toast('Insufficient funds');return}if(state.condition>=100){toast('Rig integrity already at 100%');return}state.money-=280;state.condition=Math.min(100,state.condition+35);toast('Rig serviced · integrity restored');updateHud();openShop('equipment');save()}
function openLab(){const body=`<div class="upgrade-list">${upgrades.map(u=>{const level=state.upgrades[u.id],price=u.base*Math.pow(1.7,level);return `<div class="upgrade-row"><div class="upgrade-badge">${u.symbol}</div><div class="upgrade-info"><b>${u.name}</b><small>${u.desc}</small></div><span class="upgrade-level">LV ${level}</span><button class="buy-btn" data-upgrade="${u.id}" ${state.money<price?'disabled':''}>$${money(price)}</button></div>`}).join('')}</div><div class="modal-foot"><span>RESEARCH & DEVELOPMENT</span><span>FIELD RIG · BL-07</span></div>`;showModal('Research & upgrades','Invest in deeper, safer and more efficient drilling.','BIG CRACK LAB · R&D WING',body);$('modal').querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>buyUpgrade(b.dataset.upgrade));}
function buyUpgrade(id){const u=upgrades.find(x=>x.id===id),price=Math.floor(u.base*Math.pow(1.7,state.upgrades[id]));if(state.money<price){toast('Insufficient funds for this research');return}state.money-=price;state.upgrades[id]++;if(id==='durability')state.condition=Math.min(100,state.condition+10);toast(`${u.name} upgraded to level ${state.upgrades[id]}`);updateHud();openLab();save()}
function openQuiz(){state.running=false;state.powered=false;state.monster=true;state.modal='quiz';state.quizIndex=Math.floor(Math.random()*questions.length);renderQuiz();$('modal-backdrop').classList.add('open');updateHud()}
function renderQuiz(){const q=questions[state.quizIndex];$('modal').innerHTML=`<div class="modal-head"><div><div class="eyebrow">⚡ GRID FAILURE · FIELD RESTORE</div><h2>Power interruption</h2><p>Unknown activity detected near the perimeter. Complete a science check to reset the breaker.</p></div></div><div class="modal-body"><div class="quiz"><div class="question-no">EARTH SCIENCE · ${Math.random()>.5?'FIELD BASICS':'GEOLOGY '+(state.depth>35000?'II':'I')}</div><h3>${q.q}</h3></div><div class="answer-list">${q.a.map((a,i)=>`<button class="answer-btn" data-answer="${i}">${String.fromCharCode(65+i)}. &nbsp;${a}</button>`).join('')}</div><div class="result-note" id="answer-note">Choose the correct answer to restore power to the site.</div><div class="warning-strip">⚠ RIG SHUTDOWN · SECURITY LIGHTS ON BACKUP GENERATOR</div><div class="modal-foot"><span>FIELD KNOWLEDGE CHECK</span><span>1 QUESTION · NO TIME LIMIT</span></div></div>`;$('modal').querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(+b.dataset.answer));}
function answer(i){const q=questions[state.quizIndex],buttons=$('modal').querySelectorAll('[data-answer]'),note=$('answer-note');if(i===q.c){buttons[i].classList.add('correct');note.textContent='Correct. '+q.n;note.style.color='#477954';setTimeout(()=>{state.powered=true;state.monster=false;state.outageTimer=0;state.nextOutage=80+Math.random()*65;state.running=state.oil>0&&state.condition>0;closeModal();toast('GRID RESTORED · Rig systems back online');updateHud();playTone(540,.14);save()},950)}else{buttons[i].classList.add('wrong');note.textContent='Not quite. Review the layers and try again.';note.style.color='#a85243';setTimeout(()=>buttons[i].classList.remove('wrong'),700)}}
function openCameras(){state.camera=0;const body=`<div class="camera-screen"><canvas id="feed-canvas" width="800" height="420"></canvas><div class="camera-rec"><i></i> REC · LIVE</div><div class="cam-timestamp" id="cam-time">${fmtClock()}</div><div class="cam-label" id="cam-label">CAM 01 · MAIN ENTRANCE</div></div><div class="camera-tabs">${cameras.map((c,i)=>`<button class="cam-tab ${i===0?'active':''}" data-camera="${i}">0${i+1} · ${c.toUpperCase()}</button>`).join('')}</div><div class="camera-status">● SECURE CONNECTION <span style="float:right">SIGNAL 98% · ${money(state.depth)} M DEPTH</span></div><div class="modal-foot"><span>SECURITY NETWORK · 6 ACTIVE FEEDS</span><span>BL-07 / CCTV</span></div>`;showModal('Security monitoring','Remote camera network · all feeds encrypted','CONTROL ROOM · CCTV ARRAY',body);state.modal='camera';$('modal').querySelectorAll('[data-camera]').forEach(b=>b.onclick=()=>{state.camera=+b.dataset.camera;$('modal').querySelectorAll('[data-camera]').forEach(x=>x.classList.toggle('active',+x.dataset.camera===state.camera));drawFeed()});drawFeed();}
function drawFeed(){const c=$('feed-canvas');if(!c)return;const f=c.getContext('2d'),n=state.camera,names=['MAIN ENTRANCE','MINING RIG','BIG CRACK LAB','OIL STATION','UNDERGROUND BORE','OUTER PERIMETER'];const grad=f.createLinearGradient(0,0,0,420);grad.addColorStop(0,n===4?'#281d19':'#a0b290');grad.addColorStop(.63,n===4?'#513427':'#668060');grad.addColorStop(1,n===4?'#160f0c':'#303e32');f.fillStyle=grad;f.fillRect(0,0,800,420);f.fillStyle='#19241b35';f.fillRect(0,0,800,420);
  if(n===4){for(let i=0;i<5;i++){f.fillStyle=['#a7643d','#d17f48','#e0a55c','#ba5e39','#f1c47b'][i];f.beginPath();f.ellipse(386,210,220-i*31,70-i*8,0,0,Math.PI*2);f.fill()}f.fillStyle='#f0da9c';f.font='bold 22px DM Mono';f.fillText(`DEPTH: ${money(state.depth)} M`,28,52);f.font='12px DM Mono';f.fillStyle='#e9b873';f.fillText(`GEOLOGICAL LAYER: ${layers[currentLayer()].short}`,30,78);f.strokeStyle='#ffe0a6';f.lineWidth=2;f.beginPath();f.moveTo(400,96);f.lineTo(400,334);f.stroke();}
  else{f.fillStyle='#899776';f.beginPath();f.moveTo(0,230);f.lineTo(800,215);f.lineTo(800,420);f.lineTo(0,420);f.fill();if(n===1){f.fillStyle='#4b5c53';f.fillRect(333,66,125,275);f.strokeStyle='#aeb8a1';f.lineWidth=8;f.strokeRect(333,66,125,275);for(let y=90;y<330;y+=45){f.beginPath();f.moveTo(333,y);f.lineTo(458,y);f.stroke()}f.fillStyle='#172822';f.fillRect(388,91,15,243);f.fillStyle='#d5bc71';f.fillText('RIG 01',340,370)}else{const bx=n===2?260:n===3?380:n===5?180:310;f.fillStyle=n===3?'#747f70':'#b8b9a5';f.fillRect(bx,150,n===3?180:240,166);f.fillStyle='#455a50';f.fillRect(bx+20,177,200,9);for(let i=0;i<4;i++){f.fillStyle='#365f5a';f.fillRect(bx+22+i*49,205,29,39)}f.fillStyle='#3c493c';f.fillRect(bx+103,272,35,44);f.fillStyle='#e4d49b';f.font='bold 17px DM Mono';f.fillText(n===2?'BIG CRACK LAB':n===3?'OIL STATION':n===5?'PERIMETER NORTH':'MAIN ENTRANCE',bx+14,347)}if(state.monster&&n===5){f.fillStyle='#14201e';f.beginPath();f.ellipse(670,252,19,49,0,0,Math.PI*2);f.fill();f.beginPath();f.arc(670,194,12,0,Math.PI*2);f.fill();f.fillStyle='#f6cc9a';f.fillRect(665,191,3,2);f.fillRect(672,191,3,2)}}
  // CRT scanlines, crosshair, corner bracket
  f.fillStyle='#1b25151b';for(let y=0;y<420;y+=4)f.fillRect(0,y,800,1);f.strokeStyle='#e5efd35c';f.lineWidth=1;f.beginPath();f.moveTo(384,210);f.lineTo(416,210);f.moveTo(400,194);f.lineTo(400,226);f.stroke();f.font='11px DM Mono';f.fillStyle='#e8f0db';f.fillText(`CAM 0${n+1} · ${names[n]}`,25,394);f.fillText('BL-07 // ENCRYPTED',610,394);$('cam-time').textContent=`DAY ${state.day} · ${fmtClock()}`;$('cam-label').textContent=`CAM 0${n+1} · ${names[n]}`;}
function openLayers(){const body=`<div class="layer-list">${layers.map((l,i)=>`<div class="layer-row ${i===currentLayer()?'current':''}"><i class="layer-dot"></i><b>${l.name}</b><small>${i===0?'0–35 km':i===1?'35–660 km':i===2?'660–2,890 km':i===3?'2,890–5,150 km':'5,150–6,371 km'}</small>${i===currentLayer()?'<span class="power-tag">CURRENT</span>':''}</div>`).join('')}</div><p class="layer-note">Depth ranges show approximate boundaries below Earth's surface. Earth's radius is about 6,371 km. The actual Kola Superdeep Borehole reached 12,262 m—still within the continental crust.</p>`;showModal('Earth’s interior','A field reference for the layers below our drill site.','GEOLOGICAL REFERENCE · R&D',body)}
function playTone(freq=440,duration=.1){if(state.muted)return;try{const ac=playTone.ac||(playTone.ac=new(window.AudioContext||window.webkitAudioContext)());const o=ac.createOscillator(),g=ac.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.035,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+duration);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+duration)}catch(e){}}

