const http = require('http'), fs=require('fs'), path=require('path');
const { chromium }=require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const root=process.cwd();
const mime={'.html':'text/html','.js':'text/javascript','.css':'text/css','.ico':'image/x-icon'};
const server=http.createServer((req,res)=>{const pathname=decodeURIComponent(new URL(req.url,'http://localhost').pathname);const file=path.join(root,pathname==='/'?'index.html':pathname);if(!file.startsWith(root)){res.writeHead(403).end();return}fs.readFile(file,(e,data)=>{if(e){res.writeHead(404).end('not found');return}res.writeHead(200,{'content-type':mime[path.extname(file)]||'application/octet-stream'}).end(data)})}).listen(0,'127.0.0.1',async()=>{
 let browser;
 try {
  browser=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox']});
  const errors=[];const bad=[];
  const page=await browser.newPage({viewport:{width:1280,height:800},deviceScaleFactor:1});
  page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});page.on('requestfailed',r=>bad.push(`${r.url()} ${r.failure()?.errorText}`));page.on('response',r=>{if(r.status()>=400)bad.push(`${r.status()} ${r.url()}`)});
  await page.goto(`http://127.0.0.1:${server.address().port}`,{waitUntil:'networkidle'});
  await page.screenshot({path:'/tmp/opencode/latest.jpg',type:'jpeg',quality:90});
  console.log('desktop',await page.evaluate(()=>({viewport:[innerWidth,innerHeight],canvas:[document.querySelector('#world').clientWidth,document.querySelector('#world').clientHeight],bodyScroll:document.body.scrollHeight,gameScroll:document.querySelector('.game-layout').scrollHeight,controls:getComputedStyle(document.querySelector('.mobile-controls')).display})));
  await page.click('#shop-button');console.log('shop opens',await page.locator('#modal').innerText().then(x=>x.slice(0,100)));
  await page.keyboard.press('Escape');await page.click('#camera-button');console.log('camera opens',await page.locator('#modal').innerText().then(x=>x.slice(0,100)));
  const mobile=await browser.newPage({viewport:{width:390,height:844},deviceScaleFactor:1,isMobile:true,hasTouch:true});mobile.on('console',m=>{if(m.type()==='error')errors.push('mobile '+m.text())});mobile.on('response',r=>{if(r.status()>=400)bad.push(`mobile ${r.status()} ${r.url()}`)});
  await mobile.goto(`http://127.0.0.1:${server.address().port}`,{waitUntil:'networkidle'});
  console.log('mobile',await mobile.evaluate(()=>({viewport:[innerWidth,innerHeight],canvas:[document.querySelector('#world').clientWidth,document.querySelector('#world').clientHeight],bodyScroll:document.body.scrollHeight,gameScroll:document.querySelector('.game-layout').scrollHeight,controls:getComputedStyle(document.querySelector('.mobile-controls')).display,joystick:document.querySelector('#joystick').getBoundingClientRect().toJSON(),use:document.querySelector('#mobile-use').getBoundingClientRect().toJSON(),sidebar:document.querySelector('.sidebar').getBoundingClientRect().toJSON()})));
  await mobile.screenshot({path:'/tmp/opencode/mobile.jpg',type:'jpeg',quality:85,fullPage:true});
  await mobile.locator('#joystick').dispatchEvent('pointerdown',{pointerId:1,clientX:49,clientY:790});await mobile.locator('#joystick').dispatchEvent('pointermove',{pointerId:1,clientX:70,clientY:790});console.log('joystick knob',await mobile.locator('#joy-knob').getAttribute('style'));
  console.log('consoleErrors',errors);console.log('badRequests',bad);
 } catch(e){console.error(e);process.exitCode=1} finally {if(browser)await browser.close();server.close()}
});
