node <<'NODE'
const http = require('http'), fs=require('fs'), path=require('path');
const { chromium }=require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const root=process.cwd(), mime={'.html':'text/html','.js':'text/javascript','.css':'text/css','.svg':'image/svg+xml'};
const server=http.createServer((req,res)=>{const pathname=decodeURIComponent(new URL(req.url,'http://localhost').pathname);const file=path.join(root,pathname==='/'?'index.html':pathname);if(!file.startsWith(root)){res.writeHead(403).end();return}fs.readFile(file,(e,data)=>{if(e){res.writeHead(404).end('not found');return}res.writeHead(200,{'content-type':mime[path.extname(file)]||'application/octet-stream'}).end(data)})}).listen(0,'127.0.0.1',async()=>{
 let browser;
 try {
  browser=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox']});
  const errors=[],bad=[];
  const page=await browser.newPage({viewport:{width:1280,height:800},deviceScaleFactor:1});
  page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});page.on('requestfailed',r=>bad.push(`${r.url()} ${r.failure()?.errorText}`));page.on('response',r=>{if(r.status()>=400)bad.push(`${r.status()} ${r.url()}`)});
  await page.goto(`http://127.0.0.1:${server.address().port}`,{waitUntil:'networkidle'});
  await page.screenshot({path:'/tmp/opencode/latest.jpg',type:'jpeg',quality:90});
  await page.click('#shop-button');const shop=await page.locator('#modal').innerText();await page.keyboard.press('Escape');
  await page.click('#camera-button');const camera=await page.locator('#modal').innerText();await page.keyboard.press('Escape');
  console.log('desktop screenshot 1280x800',await page.evaluate(()=>({canvas:[document.querySelector('#world').clientWidth,document.querySelector('#world').clientHeight],bodyScroll:document.body.scrollHeight})), 'shop',shop.includes('SUPPLY CHAIN'),'camera',camera.includes('Security monitoring'));
  const mobile=await browser.newPage({viewport:{width:390,height:844},deviceScaleFactor:1,isMobile:true,hasTouch:true});mobile.on('console',m=>{if(m.type()==='error')errors.push('mobile '+m.text())});mobile.on('response',r=>{if(r.status()>=400)bad.push(`mobile ${r.status()} ${r.url()}`)});
  await mobile.goto(`http://127.0.0.1:${server.address().port}`,{waitUntil:'networkidle'});
  const mobileMetrics=await mobile.evaluate(()=>({canvas:[document.querySelector('#world').clientWidth,document.querySelector('#world').clientHeight],scrollHeight:document.querySelector('.game-layout').scrollHeight,controls:getComputedStyle(document.querySelector('.mobile-controls')).display,joystick:document.querySelector('#joystick').getBoundingClientRect().toJSON(),objective:document.querySelector('.objective-card').getBoundingClientRect().toJSON(),sidebar:document.querySelector('.sidebar').getBoundingClientRect().toJSON()}));
  await mobile.screenshot({path:'/tmp/opencode/mobile.jpg',type:'jpeg',quality:85,fullPage:true});
  await mobile.locator('#joystick').dispatchEvent('pointerdown',{pointerId:1,clientX:49,clientY:440});await mobile.locator('#joystick').dispatchEvent('pointermove',{pointerId:1,clientX:70,clientY:440});const knob=await mobile.locator('#joy-knob').getAttribute('style');await mobile.locator('#joystick').dispatchEvent('pointerup',{pointerId:1});
  await mobile.locator('#mobile-use').dispatchEvent('pointerdown',{pointerId:2});
  console.log('mobile',mobileMetrics,'joystick response',knob,'mobile use action invoked');console.log('consoleErrors',errors);console.log('badRequests',bad);
 } catch(e){console.error(e);process.exitCode=1} finally {if(browser)await browser.close();server.close()}
});
